import os
import re
from dataclasses import dataclass
from typing import List, Dict, Any, Optional, Tuple

import requests


@dataclass
class UnsafeSpan:
    start: int
    end: int
    label: str
    score: float
    text: str


class TextContentSafety:
    """
    Uses Perspective API to flag or redact unsafe spans from text.
    Provider signal: PERSPECTIVE_API_KEY / perspectiveapi.com comments:analyze
    """

    API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"

    def __init__(
        self,
        api_key: Optional[str] = None,
        requested_attributes: Optional[Dict[str, Dict[str, Any]]] = None,
        languages: Optional[List[str]] = None,
        timeout: float = 15.0,
    ):
        self.api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
        if not self.api_key:
            raise ValueError("Missing PERSPECTIVE_API_KEY")
        self.requested_attributes = requested_attributes or {
            "TOXICITY": {},
            "SEVERE_TOXICITY": {},
            "INSULT": {},
            "THREAT": {},
            "IDENTITY_ATTACK": {},
            "SEXUALLY_EXPLICIT": {},
            "FLIRTATION": {},
        }
        self.languages = languages
        self.timeout = timeout

    def analyze(self, text: str) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "comment": {"text": text},
            "requestedAttributes": self.requested_attributes,
            "doNotStore": True,
        }
        if self.languages:
            payload["languages"] = self.languages

        resp = requests.post(
            self.API_URL,
            params={"key": self.api_key},
            json=payload,
            timeout=self.timeout,
        )
        resp.raise_for_status()
        return resp.json()

    @staticmethod
    def _get_scores(response_json: Dict[str, Any]) -> Dict[str, float]:
        attrs = response_json.get("attributeScores", {})
        scores: Dict[str, float] = {}
        for label, data in attrs.items():
            try:
                scores[label] = float(data["summaryScore"]["value"])
            except (KeyError, TypeError, ValueError):
                continue
        return scores

    @staticmethod
    def _heuristic_spans(text: str, scores: Dict[str, float], threshold: float) -> List[UnsafeSpan]:
        spans: List[UnsafeSpan] = []
        if not scores:
            return spans

        toxic_labels = [label for label, score in scores.items() if score >= threshold]
        if not toxic_labels:
            return spans

        # Lightweight span localization heuristic:
        # - scan for segments around profanity/slur-like patterns
        # - if none found, redact the full text
        patterns = [
            r"\b(fuck|shit|bitch|asshole|bastard|cunt)\b",
            r"\b(kill|die|murder|hurt you|hurt them)\b",
            r"\b(idiot|moron|stupid|retard)\b",
            r"\b(nigger|faggot|tranny)\b",
            r"\b(porn|sex|nude|naked)\b",
        ]
        matches: List[Tuple[int, int, str]] = []
        for pat in patterns:
            for m in re.finditer(pat, text, flags=re.IGNORECASE):
                matches.append((m.start(), m.end(), m.group(0)))

        if matches:
            for s, e, t in matches:
                spans.append(
                    UnsafeSpan(
                        start=s,
                        end=e,
                        label=",".join(toxic_labels),
                        score=max(scores.values()),
                        text=t,
                    )
                )
        else:
            spans.append(
                UnsafeSpan(
                    start=0,
                    end=len(text),
                    label=",".join(toxic_labels),
                    score=max(scores.values()),
                    text=text,
                )
            )
        return spans

    def flag(self, text: str, threshold: float = 0.5) -> Dict[str, Any]:
        response = self.analyze(text)
        scores = self._get_scores(response)
        spans = self._heuristic_spans(text, scores, threshold)
        return {
            "unsafe": bool(spans),
            "scores": scores,
            "spans": [span.__dict__ for span in spans],
            "raw": response,
        }

    @staticmethod
    def redact(text: str, spans: List[Dict[str, Any]], replacement: str = "[REDACTED]") -> str:
        if not spans:
            return text

        normalized: List[Tuple[int, int]] = []
        for span in spans:
            s = int(span["start"])
            e = int(span["end"])
            if s < e:
                normalized.append((s, e))

        if not normalized:
            return text

        normalized.sort()
        merged: List[Tuple[int, int]] = []
        cur_s, cur_e = normalized[0]
        for s, e in normalized[1:]:
            if s <= cur_e:
                cur_e = max(cur_e, e)
            else:
                merged.append((cur_s, cur_e))
                cur_s, cur_e = s, e
        merged.append((cur_s, cur_e))

        out = []
        last = 0
        for s, e in merged:
            out.append(text[last:s])
            out.append(replacement)
            last = e
        out.append(text[last:])
        return "".join(out)

    def flag_and_redact(self, text: str, threshold: float = 0.5, replacement: str = "[REDACTED]") -> Dict[str, Any]:
        result = self.flag(text, threshold=threshold)
        redacted = self.redact(text, result["spans"], replacement=replacement)
        result["redacted_text"] = redacted
        return result


def flag_unsafe_spans(text: str, threshold: float = 0.5) -> Dict[str, Any]:
    """
    Convenience function that returns unsafe spans and a redacted version of the text.
    """
    safety = TextContentSafety()
    return safety.flag_and_redact(text, threshold=threshold)
